'use strict';
const $=id=>document.getElementById(id),fmt=n=>n.toLocaleString('es-MX');
const BALLOT_KEY='todosimss:consulta-salarial-demo-v1:participacion';
function participationState(){try{return localStorage.getItem(BALLOT_KEY)==='1'?'voted':'ready';}catch{return 'unavailable';}}
const MIN=30;let scope={state:'',city:'',unit:''};let choice=null,currentToken=null,finished=false;const tokens=new Map();
function sum(units){return units.reduce((a,u)=>({yes:a.yes+u.yes,no:a.no+u.no}),{yes:0,no:0});}
function unitsOf(s){return s.cities.flatMap(c=>c.units);}
function safe(r){return r.yes+r.no>=MIN&&r.yes>=5&&r.no>=5;}
function pct(n,t){return (100*n/t).toFixed(1)+'%';}
function option(value,label){const o=document.createElement('option');o.value=value;o.textContent=label;return o;}
function fill(el,items,first){el.replaceChildren();if(first)el.append(option('',first));items.forEach(([v,n])=>el.append(option(v,n)));}
function selectedState(){return DATA.find(s=>s.id===scope.state);}
function selectedCity(){return selectedState()?.cities.find(c=>c.name===scope.city);}
function tab(id){if(!['panorama','votar','mesa'].includes(id))throw Error('Sección inválida');document.querySelectorAll('.content-tab').forEach(e=>e.hidden=e.id!==id);document.querySelectorAll('.tab').forEach(e=>{e.setAttribute('aria-selected',String(e.id==='t-'+id));e.tabIndex=e.id==='t-'+id?0:-1;});}
function setState(id){if(id&&!DATA.some(s=>s.id===id))throw Error('Estado inválido');scope={state:id,city:'',unit:''};$('stateSelect').value=id;fill($('citySelect'),(selectedState()?.cities||[]).map(c=>[c.name,c.name]),'Todas las ciudades');$('citySelect').disabled=!id;fill($('unitSelect'),[],'Todas las unidades');$('unitSelect').disabled=true;render();}
function setCity(name){scope.city=name;scope.unit='';fill($('unitSelect'),(selectedCity()?.units||[]).map(u=>[u.id,u.name]),'Todas las unidades');$('unitSelect').disabled=!name;render();}
function setUnit(id){scope.unit=id;render();}
function resetScope(){setState('');}
function resultHTML(title,r){const t=r.yes+r.no;if(!safe(r))return `<div class="result-title">${title}</div><div class="locked"><b>Resultado protegido</b><p class="muted tiny">No se publican cifras ni porcentajes para este grupo. La muestra es pequeña o alguna respuesta tiene pocos votos.</p></div>`;return `<div class="result-title">${title}</div><div class="breadcrumb">${fmt(t)} votos ficticios</div><div class="split" aria-hidden="true"><div class="yes" style="width:${100*r.yes/t}%"></div><div class="no" style="width:${100*r.no/t}%"></div></div><div class="numbers"><span><strong style="color:var(--green)">${pct(r.yes,t)}</strong>Sí · ${fmt(r.yes)} votos</span><span style="text-align:right"><strong style="color:var(--blue)">${pct(r.no,t)}</strong>No · ${fmt(r.no)} votos</span></div>`;}
function render(){const s=selectedState(),c=selectedCity(),u=c?.units.find(u=>u.id===scope.unit);const list=u?[u]:c?c.units:s?unitsOf(s):DATA.flatMap(unitsOf);$('scopeResult').innerHTML=resultHTML(u?.name||c?.name||s?.name||'Todo México',sum(list));document.querySelectorAll('.state').forEach(p=>p.classList.toggle('selected',p.dataset.id===scope.state));let rows;
 if(c){$('listTitle').textContent='Unidades de ejemplo · '+c.name;$('nameColumn').textContent='Unidad';rows=c.units.map(u=>({name:u.name,result:sum([u]),action:()=>{scope.unit=u.id;$('unitSelect').value=u.id;render();}}));}
 else if(s){$('listTitle').textContent='Ciudades · '+s.name;$('nameColumn').textContent='Ciudad / municipio';rows=s.cities.map(c=>({name:c.name,result:sum(c.units),action:()=>{$('citySelect').value=c.name;setCity(c.name);}}));}
 else{$('listTitle').textContent='Resultados por estado';$('nameColumn').textContent='Estado';rows=DATA.map(s=>({name:s.name,result:sum(unitsOf(s)),action:()=>setState(s.id)}));}
 $('rows').replaceChildren();rows.forEach(row=>{const tr=document.createElement('tr'),td=document.createElement('td'),btn=document.createElement('button');btn.textContent=row.name;btn.onclick=row.action;td.append(btn);tr.append(td);const r=row.result,t=r.yes+r.no;const vals=safe(r)?[fmt(t),pct(r.yes,t),pct(r.no,t)]:['Protegido','—','—'];vals.forEach(v=>{const e=document.createElement('td');e.textContent=v;tr.append(e);});$('rows').append(tr);});}
function buildMap(){const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 960 670');svg.setAttribute('role','group');svg.setAttribute('aria-label','32 entidades de México. Selecciona un estado para consultar sus resultados ficticios.');DATA.forEach(s=>{const r=sum(unitsOf(s)),t=r.yes+r.no;const p=document.createElementNS(ns,'path');p.setAttribute('d',s.path);p.setAttribute('fill',safe(r)?`hsl(213 58% ${90-58*r.no/t}%)`:'#dce4e8');p.setAttribute('fill-rule','evenodd');p.classList.add('state');p.dataset.id=s.id;p.setAttribute('role','button');p.setAttribute('tabindex','0');p.setAttribute('aria-label',s.name+', '+(safe(r)?pct(r.no,t)+' No, datos ficticios':'resultado protegido'));const title=document.createElementNS(ns,'title');title.textContent=s.name+' · '+(safe(r)?pct(r.no,t)+' No':'Protegido');p.append(title);p.onclick=()=>setState(s.id);p.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setState(s.id);}};svg.append(p);});const txt=document.createElementNS(ns,'text');txt.setAttribute('x','130');txt.setAttribute('y','490');txt.classList.add('ocean');txt.textContent='OCÉANO PACÍFICO';svg.append(txt);const gulf=document.createElementNS(ns,'text');gulf.setAttribute('x','625');gulf.setAttribute('y','330');gulf.classList.add('ocean');gulf.textContent='GOLFO DE MÉXICO';svg.append(gulf);$('map').append(svg);}
function voteScope(){return [$('voteState').value,$('voteCity').value,$('voteUnit').value].join('|');}
function invalidateCode(){currentToken=null;$('shownCode').textContent='';$('codeInput').value='';choice=null;document.querySelectorAll('.choice').forEach(b=>b.setAttribute('aria-pressed','false'));if(!finished)$('voteStatus').textContent='';}
function updateVoteCities(){const s=DATA.find(s=>s.id===$('voteState').value);fill($('voteCity'),s.cities.map(c=>[c.name,c.name]));updateVoteUnits();}
function updateVoteUnits(){const s=DATA.find(s=>s.id===$('voteState').value),c=s.cities.find(c=>c.name===$('voteCity').value);fill($('voteUnit'),c.units.map(u=>[u.id,u.name]));invalidateCode();}
function generateCode(){if(finished||participationState()!=='ready'){applyParticipationLock();return;}if(currentToken)tokens.delete(currentToken);const a=new Uint32Array(2);crypto.getRandomValues(a);currentToken='DEMO-'+Array.from(a,n=>n.toString(36).toUpperCase()).join('-');tokens.set(currentToken,{scope:voteScope(),used:false});$('shownCode').textContent=currentToken;$('codeInput').value='';$('voteStatus').className='status';$('voteStatus').textContent='Código generado. Escríbelo arriba para probar el acceso.';}
function choose(value){if(finished)return;choice=value;document.querySelectorAll('.choice').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.value===value)));}
async function submitVote(){if(finished)return;if(!navigator.locks){$('voteStatus').className='status error';$('voteStatus').textContent='Este navegador no permite coordinar pestañas. Prueba un navegador actualizado.';return;}await navigator.locks.request(BALLOT_KEY,()=>submitVoteLocked());}
function submitVoteLocked(){if(finished||participationState()!=='ready'){applyParticipationLock();return;}const code=$('codeInput').value.trim().toUpperCase(),record=tokens.get(code);let error='';if(!record)error='Código de prueba inválido. Genera uno para la ubicación seleccionada.';else if(record.used)error='Este código ya fue utilizado.';else if(record.scope!==voteScope())error='Este código corresponde a otra ubicación. Genera uno nuevo.';else if(!choice)error='Selecciona Sí o No antes de confirmar.';if(error){$('voteStatus').className='status error';$('voteStatus').textContent=error;return;}try{localStorage.setItem(BALLOT_KEY,'1');if(localStorage.getItem(BALLOT_KEY)!=='1')throw Error('Storage');}catch{$('voteStatus').className='status error';$('voteStatus').textContent='No se pudo guardar la marca de participación. No se aceptó el ensayo.';return;}record.used=true;finished=true;choice=null;$('codeInput').value='';$('shownCode').textContent='';document.querySelectorAll('.choice').forEach(b=>{b.setAttribute('aria-pressed','false');b.disabled=true;});$('submitVote').disabled=true;$('voteStatus').textContent='';$('voteSuccess').classList.remove('hidden');['voteState','voteCity','voteUnit','codeInput'].forEach(id=>$(id).disabled=true);}
function applyParticipationLock(){const state=participationState();if(state==='ready')return;finished=true;['voteState','voteCity','voteUnit','codeInput','submitVote','generateCode'].forEach(id=>$(id).disabled=true);document.querySelectorAll('.choice').forEach(b=>{b.disabled=true;b.setAttribute('aria-pressed','false');});$('shownCode').textContent='';$('codeInput').value='';choice=null;currentToken=null;tokens.clear();$('voteStatus').className='status';$('voteStatus').textContent=state==='voted'?'Este navegador ya participó en esta consulta de prueba. Puedes seguir explorando los resultados.':'El almacenamiento está bloqueado. No es posible realizar el ensayo en este navegador.';}
window.addEventListener('storage',e=>{if(e.key===BALLOT_KEY||e.key===null)applyParticipationLock();});
fill($('stateSelect'),DATA.map(s=>[s.id,s.name]),'Todo México');fill($('voteState'),DATA.map(s=>[s.id,s.name]));$('voteState').value=DATA.find(s=>s.name==='Sonora').id;updateVoteCities();buildMap();resetScope();const national=sum(DATA.flatMap(unitsOf)),nt=national.yes+national.no;$('total').textContent=fmt(nt);$('nationalYes').textContent=pct(national.yes,nt);$('nationalNo').textContent=pct(national.no,nt);
document.querySelector('.tabs').addEventListener('keydown',e=>{const ids=['panorama','votar','mesa'],index=ids.findIndex(id=>$('t-'+id).getAttribute('aria-selected')==='true');let next;if(e.key==='ArrowRight')next=(index+1)%3;if(e.key==='ArrowLeft')next=(index+2)%3;if(e.key==='Home')next=0;if(e.key==='End')next=2;if(next!==undefined){e.preventDefault();tab(ids[next]);$('t-'+ids[next]).focus();}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'explorar_estado',title:'Explorar resultados ficticios por estado',description:'Selecciona un estado del mapa y muestra sus resultados ficticios agrupados. No emite un voto.',inputSchema:{type:'object',properties:{estado:{type:'string'}},required:['estado'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.estado!=='string')throw Error('Especifica un estado');const s=DATA.find(s=>s.name===input.estado);if(!s)throw Error('Estado no encontrado');tab('panorama');setState(s.id);return {estado:s.name,datos:'ficticios',resultado:sum(unitsOf(s))};}})).catch(()=>{});}catch{}}

applyParticipationLock();
